import{_ as r,b as s,e as t,a7 as i}from"./chunks/framework.BCCJKnGb.js";const m=JSON.parse('{"title":"培养方案总览","description":"国新系 2023–2026 级培养方案索引、使用说明与版本说明。","frontmatter":{"title":"培养方案总览","description":"国新系 2023–2026 级培养方案索引、使用说明与版本说明。","type":"program-index","tags":["培养方案","国新系"],"updated":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"programs/index.md","filePath":"programs/index.md","lastUpdated":null}'),e={name:"programs/index.md"};function o(l,a,d,p,n,c){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="培养方案总览" tabindex="-1">培养方案总览 <a class="header-anchor" href="#培养方案总览" aria-label="Permalink to &quot;培养方案总览&quot;">​</a></h1><p>先选自己的年级，再看三件事：<strong>学分模块是否修满、必修课是否按学期修、先修关系有没有卡住</strong>。</p><div class="card-grid"><div class="card"><h3>2023 级</h3><p>总学分 137；通识 48 / 专业 69 / 创新 10 / 素质 10。</p><p><a href="/programs/2023">查看 →</a></p></div><div class="card"><h3>2024 级</h3><p>总学分 136；通识 47 / 专业 69 / 创新 10 / 素质 10。</p><p><a href="/programs/2024">查看 →</a></p></div><div class="card"><h3>2025 级</h3><p>总学分 132；立本 49 / 专业 67 / 卓越 16。</p><p><a href="/programs/2025">查看 →</a></p></div><div class="card"><h3>2026 级</h3><p>总学分 127；立本 46 / 专业 65 / 卓越 16。</p><p><a href="/programs/2026">查看 →</a></p></div><div class="card"><h3>学分核对</h3><p>上传成绩单，按培养方案看已修学分与缺口。</p><p><a href="/programs/credit-audit">开始 →</a></p></div></div><div class="tip custom-block"><p class="custom-block-title">课程外学分</p><p>除了课程，还有 8 类非课程必修学分（思政实践、形势与政策、劳动、志愿、讲座、职业、研究训练、心理），合计约 13–14 学分。详见 <a href="/mingxin-demo/programs/non-course">课程外必修学分</a>。</p></div><h2 id="怎么读培养方案" tabindex="-1">怎么读培养方案 <a class="header-anchor" href="#怎么读培养方案" aria-label="Permalink to &quot;怎么读培养方案&quot;">​</a></h2><ol><li><strong>先看学分模块</strong>：通识、部类、专业必修、专业选修、实践、毕业论文，各要多少分。</li><li><strong>再看学期分布</strong>：哪些课只在秋季/春季开，错过会不会影响先修。</li><li><strong>最后看备注</strong>：实验班、国际交流、辅修/双学位、替代课程的特殊规则。</li></ol><h2 id="版本与来源" tabindex="-1">版本与来源 <a class="header-anchor" href="#版本与来源" aria-label="Permalink to &quot;版本与来源&quot;">​</a></h2><ul><li>每个年级页面都标注“适用年级、最后更新、来源”。</li><li>培养方案会调整；页面与教务系统不一致时，<strong>以教务系统/学院最新通知为准</strong>。</li><li>旧版本保留，不覆盖；页面上可以直接看到版本差异。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>本站是学习规划辅助，不做学分认定，也不能替代教务系统的选课/毕业审核。涉及毕业学分、推免资格等关键事项，请以学院教务老师答复为准。</p></div>',9)])])}const g=r(e,[["render",o]]);export{m as __pageData,g as default};
